import{_ as o,r as n,o as p,c,e as a,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"数据库配置 - October CMS - 3.x","titleTemplate":false,"description":"了解如何配置数据库层。","frontmatter":{"subtitle":"了解如何配置数据库层。"},"headers":[{"level":2,"title":"SQLite 配置","slug":"sqlite-配置","link":"#sqlite-配置","children":[]},{"level":2,"title":"读/写连接","slug":"读-写连接","link":"#读-写连接","children":[]},{"level":2,"title":"使用 MySQL / MariaDB 时的索引长度","slug":"使用-mysql-mariadb-时的索引长度","link":"#使用-mysql-mariadb-时的索引长度","children":[]}],"relativePath":"3.x/zh-cn/setup/database-config.md","filePath":"3.x/zh-cn/setup/database-config.md"}'),r={name:"3.x/zh-cn/setup/database-config.md"};function d(g,s,u,k,q,h){const t=n("pre-heading"),e=n("post-heading");return p(),c("div",null,[a(t),s[0]||(s[0]=i("h1",null,"数据库配置",-1)),a(e),s[1]||(s[1]=l(`<p>应用程序的数据库配置位于 <code>config/database.php</code> 文件中。在此文件中，您可以定义所有数据库连接，并指定默认使用的连接。该文件中提供了所有受支持数据库系统的示例。</p><h2 id="sqlite-配置"><a href="#sqlite-配置" class="header-anchor">#</a> SQLite 配置</h2><p>SQLite 数据库使用文件系统上的单个文件。要创建新的 SQLite 数据库，请使用 <code>touch</code> 命令。</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">touch</span> storage/database.sqlite
</code></pre></div><p>之后，您可以通过将绝对路径填入 <code>DB_DATABASE</code> 变量来配置环境变量以使用该数据库。</p><div class="language-text extra-class"><pre class="language-text"><code>DB_CONNECTION=sqlite
DB_DATABASE=/absolute/path/to/database.sqlite
</code></pre></div><h2 id="读-写连接"><a href="#读-写连接" class="header-anchor">#</a> 读/写连接</h2><p>有时您可能希望使用一个数据库连接处理 SELECT 语句，而使用另一个连接处理 INSERT、UPDATE 和 DELETE 语句。无论您使用的是原始查询、查询构建器还是模型，都可以轻松指定所使用的连接。</p><p>要了解如何配置读/写连接，请看以下示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mysql&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;read&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;192.168.1.1&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;write&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;196.168.1.2&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;driver&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;mysql&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;database&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;database&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;username&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;root&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;charset&#39;</span>   <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;collation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8_unicode_ci&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;prefix&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>请注意，配置数组中添加了两个键：<code>read</code> 和 <code>write</code>。这两个键的数组值都包含一个键：<code>host</code>。<code>read</code> 和 <code>write</code> 连接的其余数据库选项将从主 <code>mysql</code> 数组中合并。</p><p>我们只需要在 <code>read</code> 和 <code>write</code> 数组中放置希望覆盖主数组值的项目。因此，在本例中，<code>192.168.1.1</code> 将用作&quot;读&quot;连接，而 <code>192.168.1.2</code> 将用作&quot;写&quot;连接。主 <code>mysql</code> 数组中的数据库凭据、前缀、字符集以及所有其他选项将在两个连接之间共享。</p><p><a id="oc-index-lengths-using-mysql-mariadb"></a></p><h2 id="使用-mysql-mariadb-时的索引长度"><a href="#使用-mysql-mariadb-时的索引长度" class="header-anchor">#</a> 使用 MySQL / MariaDB 时的索引长度</h2><p>默认情况下，October CMS 使用 <code>utf8mb4</code> 字符集。如果运行的 MySQL 版本低于 v5.7.7 或 MariaDB 版本低于 v10.2.2，您需要手动配置迁移生成的默认字符串长度，以便 MySQL 能够为其创建索引。要配置默认字符串长度，请将以下内容添加到 <strong>config/database.php</strong> 配置文件中的 <code>connections.mysql</code> 键下。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mysql&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token comment">// ...</span>
    <span class="token string single-quoted-string">&#39;varcharmax&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">191</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div>`,16))])}const b=o(r,[["render",d]]);export{_ as __pageData,b as default};
